const nArg = process.argv[2];
const N = nArg ? parseInt(nArg, 10) : 0;

function fannkuchRedux(n: number): { checksum: number; maxFlips: number } {
  if (n <= 0) return { checksum: 0, maxFlips: 0 };

  const perm = new Int32Array(n);
  const perm1 = new Int32Array(n);
  const count = new Int32Array(n);

  for (let i = 0; i < n; i++) perm1[i] = i;

  let checksum = 0;
  let maxFlips = 0;
  let sign = 1;

  while (true) {
    // Copy current permutation
    for (let i = 0; i < n; i++) perm[i] = perm1[i];

    // Compute flips for this permutation
    let flips = 0;
    if (perm[0] !== 0) {
      while (perm[0] !== 0) {
        const k = perm[0] + 1;
        for (let i = 0, j = k - 1; i < j; i++, j--) {
          const t = perm[i];
          perm[i] = perm[j];
          perm[j] = t;
        }
        flips++;
      }
    }

    checksum += sign * flips;
    if (flips > maxFlips) maxFlips = flips;

    // Generate next permutation using factoradic count array
    let i = 1;
    while (i < n) {
      const c = count[i];
      if (c < i) {
        const first = perm1[0];
        for (let j = 0; j < i; j++) perm1[j] = perm1[j + 1];
        perm1[i] = first;
        count[i] = c + 1;
        sign = -sign;
        break;
      } else {
        count[i] = 0;
        i++;
        if (i === n) {
          return { checksum, maxFlips };
        }
        const first = perm1[0];
        for (let j = 0; j < i; j++) perm1[j] = perm1[j + 1];
        perm1[i] = first;
        sign = -sign;
      }
    }
  }
}

const result = fannkuchRedux(N);
process.stdout.write(`${result.checksum}\nPfannkuchen(${N}) = ${result.maxFlips}\n`);
