import * as fs from "fs";

const input = fs.readFileSync(0, "utf8");

// Extract sequence lines from FASTA, skip headers, normalize to uppercase.
let seqParts: string[] = [];
for (const line of input.split(/\r?\n/)) {
  if (!line || line.charCodeAt(0) === 62) continue; // '>'
  seqParts.push(line.trim());
}
const seq = seqParts.join("").toUpperCase();
const n = seq.length;

function countKmers(k: number): Map<string, number> {
  const counts = new Map<string, number>();
  if (n < k) return counts;

  for (let i = 0; i <= n - k; i++) {
    const s = seq.slice(i, i + k);
    counts.set(s, (counts.get(s) || 0) + 1);
  }
  return counts;
}

function printFrequencies(k: number): void {
  const counts = countKmers(k);
  const total = n - k + 1;
  const arr = Array.from(counts.entries());
  arr.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1];
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
  });

  let out = "";
  for (const [frag, cnt] of arr) {
    const pct = ((cnt * 100) / total).toFixed(3);
    out += `${frag} ${pct}\n`;
  }
  process.stdout.write(out);
}

function printCount(fragment: string, counts: Map<string, number>): void {
  process.stdout.write(`${counts.get(fragment) || 0}\t${fragment}\n`);
}

// 1-mer and 2-mer frequencies
printFrequencies(1);
printFrequencies(2);

// Specific fragment counts
const targets = [
  "GGT",
  "GGTA",
  "GGTATT",
  "GGTATTTTAATT",
  "GGTATTTTAATTTATAGT",
];
const maxK = Math.max(...targets.map(t => t.length));
const allCounts = new Map<number, Map<string, number>>();
for (let k = 3; k <= maxK; k++) {
  allCounts.set(k, countKmers(k));
}
for (const t of targets) {
  printCount(t, allCounts.get(t.length)!);
}
