const width = N | 0;
const height = width;

let out = `P4\n${width} ${height}\n`;
process.stdout.write(out);

const maxIter = 50;
const invW = 2.0 / width;
const invH = 2.0 / height;

const rowBytes = (width + 7) >> 3;
const row = Buffer.allocUnsafe(rowBytes);

for (let y = 0; y < height; y++) {
  const ci = y * invH - 1.0;
  let byte = 0;
  let bitCount = 0;
  let rowPos = 0;

  for (let x = 0; x < width; x++) {
    const cr = x * invW - 1.5;

    let zr = 0.0;
    let zi = 0.0;
    let iter = 0;

    while (iter < maxIter) {
      const zr2 = zr * zr;
      const zi2 = zi * zi;
      if (zr2 + zi2 > 4.0) break;
      zi = 2.0 * zr * zi + ci;
      zr = zr2 - zi2 + cr;
      iter++;
    }

    byte = (byte << 1) | (iter === maxIter ? 1 : 0);
    bitCount++;

    if (bitCount === 8) {
      row[rowPos++] = byte;
      byte = 0;
      bitCount = 0;
    }
  }

  if (bitCount !== 0) {
    byte <<= (8 - bitCount);
    row[rowPos++] = byte;
  }

  process.stdout.write(row.subarray(0, rowPos));
}
